#!/usr/bin/env node
// Differential harness: runs the Python executable and the Node port with the
// same argv and reports any divergence in stdout, stderr or exit status.
// The program name legitimately differs, so it is normalised before comparing.
import { spawnSync } from 'node:child_process';

const PY = '/workspace/dataset/test5_executable';
const JS = ['/output/test5.mjs'];

function normalise(text) {
  return text.split('test5_executable').join('«PROG»').split('test5.mjs').join('«PROG»');
}

export function compare(argv, env = {}) {
  const options = { encoding: 'buffer', env: { ...process.env, ...env } };
  const py = spawnSync(PY, argv, options);
  const js = spawnSync(process.execPath, [...JS, ...argv], options);
  const result = {
    argv,
    env,
    ok: true,
    py: {
      stdout: py.stdout.toString('utf8'),
      stderr: py.stderr.toString('utf8'),
      status: py.status,
    },
    js: {
      stdout: js.stdout.toString('utf8'),
      stderr: js.stderr.toString('utf8'),
      status: js.status,
    },
  };
  result.ok =
    normalise(result.py.stdout) === normalise(result.js.stdout) &&
    normalise(result.py.stderr) === normalise(result.js.stderr) &&
    result.py.status === result.js.status;
  return result;
}

export function report(cases) {
  let failures = 0;
  for (const testCase of cases) {
    const argv = Array.isArray(testCase) ? testCase : testCase.argv;
    const env = Array.isArray(testCase) ? {} : (testCase.env ?? {});
    const result = compare(argv, env);
    if (!result.ok) {
      failures += 1;
      console.log('MISMATCH', JSON.stringify({ argv, env }));
      console.log('  py:', JSON.stringify(result.py));
      console.log('  js:', JSON.stringify(result.js));
    }
  }
  console.log(`${cases.length - failures}/${cases.length} matched`);
  return failures;
}

if (process.argv[1] && process.argv[1].endsWith('difftest.mjs') && process.argv.length > 2) {
  const result = compare(process.argv.slice(2));
  console.log(JSON.stringify(result, null, 2));
  process.exit(result.ok ? 0 : 1);
}

/**
 * Port of dataset/networkx/test5.py.
 *
 *   import argparse
 *   import networkx as nx
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--a', type=int, required=True)
 *   ... (--b, --c, --d, --e)
 *   args = parser.parse_args()
 *
 *   G = nx.DiGraph()
 *   G.add_edges_from([(args.a, args.b), (args.b, args.c), (args.c, args.d), (args.d, args.e)])
 *   print(nx.is_directed_acyclic_graph(G))
 *
 * Run it as: node test5.mjs --a 1 --b 2 --c 3 --d 4 --e 5
 */

import { ArgumentParser } from './lib/argparse/index.mjs';
import * as nx from './lib/networkx/index.mjs';
import { int, pyStr, SystemExit } from './lib/python/index.mjs';

function main() {
  const parser = new ArgumentParser();
  parser.add_argument('--a', { type: int, required: true });
  parser.add_argument('--b', { type: int, required: true });
  parser.add_argument('--c', { type: int, required: true });
  parser.add_argument('--d', { type: int, required: true });
  parser.add_argument('--e', { type: int, required: true });
  const args = parser.parse_args();

  const G = new nx.DiGraph();
  G.add_edges_from([
    [args.a, args.b],
    [args.b, args.c],
    [args.c, args.d],
    [args.d, args.e],
  ]);
  console.log(pyStr(nx.is_directed_acyclic_graph(G))); // 检查是否为有向无环图
}

try {
  main();
} catch (error) {
  // argparse leaves through SystemExit; anything else is a genuine crash.
  if (error instanceof SystemExit) process.exit(error.code);
  throw error;
}
