/**
 * Unicode character classification mirroring the CPython predicates that the
 * ported code depends on.
 *
 * Everything here is derived from the runtime's own Unicode tables via regular
 * expression property escapes, so no character data is bundled or vendored.
 */

const RE_DECIMAL_DIGIT = /^\p{Nd}$/u;

/**
 * `str.isprintable()` treats a character as non-printable when its general
 * category is one of Cc, Cf, Cs, Co, Cn, Zl, Zp or Zs -- with the single space
 * U+0020 carved out as printable.
 */
const RE_NONPRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

/**
 * The ASCII characters `Py_ISSPACE` accepts. Note that this is deliberately
 * narrower than `str.isspace()`: the C-level table used while scanning a
 * numeric literal does not include U+001C..U+001F, which is why `int('\x1c5')`
 * fails while `int('\x0b5')` succeeds.
 */
const ASCII_SPACES = new Set([0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20]);

/**
 * `Py_UNICODE_ISSPACE` for the code points above the ASCII range. These are the
 * characters that get folded to a plain space before a numeric literal is
 * scanned.
 */
const NON_ASCII_SPACES = new Set([
  0x0085, 0x00a0, 0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f,
  0x3000,
]);

/** Memo table for {@link decimalValue}; digit runs are scanned at most once. */
const digitValues = new Map();

export function isAsciiSpace(codePoint) {
  return ASCII_SPACES.has(codePoint);
}

export function isNonAsciiSpace(codePoint) {
  return NON_ASCII_SPACES.has(codePoint);
}

export function isDecimalDigit(codePoint) {
  return RE_DECIMAL_DIGIT.test(String.fromCodePoint(codePoint));
}

export function isPrintable(codePoint) {
  if (codePoint === 0x20) return true;
  return !RE_NONPRINTABLE.test(String.fromCodePoint(codePoint));
}

/**
 * `Py_UNICODE_TODECIMAL`: the numeric value of a decimal digit, or -1.
 *
 * Unicode lays every decimal digit set out as ten consecutive code points
 * starting at that script's ZERO, but consecutive sets can sit back to back --
 * the mathematical alphanumerics pack five of them into U+1D7CE..U+1D7FF. So
 * walking down to the first non-digit finds the head of the whole contiguous
 * block rather than of one set, and the offset has to be reduced modulo ten.
 */
export function decimalValue(codePoint) {
  const memo = digitValues.get(codePoint);
  if (memo !== undefined) return memo;

  let value = -1;
  if (isDecimalDigit(codePoint)) {
    let blockStart = codePoint;
    while (blockStart > 0 && isDecimalDigit(blockStart - 1)) blockStart -= 1;
    value = (codePoint - blockStart) % 10;
  }

  digitValues.set(codePoint, value);
  return value;
}

