/**
 * Python's `repr()` and `str()` for the handful of types this port formats.
 *
 * argparse embeds `%r` of the offending string in its type-error messages and
 * `print(True)` has to come out as `True`, so both spellings are needed.
 */

import { isPrintable } from './unicode.mjs';

const SHORT_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\t', '\\t'],
  ['\n', '\\n'],
  ['\r', '\\r'],
]);

function escapeCodePoint(codePoint) {
  if (codePoint < 0x100) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint < 0x10000) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

/**
 * `repr()` of a string: single quotes unless the text contains a single quote
 * and no double quote, backslash/tab/newline/carriage-return escaped in short
 * form, and every non-printable code point escaped numerically.
 *
 * @param {string} text
 * @returns {string}
 */
export function reprString(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";

  let out = quote;
  for (const character of text) {
    if (character === quote) {
      out += `\\${character}`;
      continue;
    }
    const short = SHORT_ESCAPES.get(character);
    if (short !== undefined) {
      out += short;
      continue;
    }
    const codePoint = character.codePointAt(0);
    out += isPrintable(codePoint) ? character : escapeCodePoint(codePoint);
  }
  return out + quote;
}

/**
 * `str()`/`print()` of a value. Booleans are the reason this exists: Python
 * spells them `True` and `False`.
 *
 * @param {unknown} value
 * @returns {string}
 */
export function pyStr(value) {
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'string') return value;
  return String(value);
}

/**
 * `repr()` of a value: like {@link pyStr} except strings come back quoted.
 *
 * @param {unknown} value
 * @returns {string}
 */
export function pyRepr(value) {
  if (typeof value === 'string') return reprString(value);
  return pyStr(value);
}
