/**
 * The slice of `textwrap` that argparse's help formatter exercises.
 *
 * Callers hand in text whose whitespace has already been collapsed to single
 * spaces (that is what `HelpFormatter._split_lines` does), so the elaborate
 * whitespace bookkeeping of the original is unnecessary; the greedy filling,
 * hyphen-aware splitting and long-word breaking below follow
 * `TextWrapper._split`/`_wrap_chunks`/`_handle_long_word` step for step.
 */

import { PyValueError } from './errors.mjs';

/** A hyphen that `break_on_hyphens` is allowed to split after. */
const HYPHEN_BREAK = /(?<=[A-Za-z]{2})-(?=[A-Za-z]-?[A-Za-z])/g;

function isBlank(chunk) {
  return chunk.trim() === '';
}

/**
 * `TextWrapper._split`: whitespace runs and words become separate chunks, and
 * hyphenated words are split so a line may break after the hyphen.
 */
function splitChunks(text) {
  const chunks = [];
  for (const piece of text.split(/(\s+)/)) {
    if (piece === '') continue;
    if (isBlank(piece)) {
      chunks.push(piece);
      continue;
    }
    for (const part of piece.replace(HYPHEN_BREAK, '-�').split('�')) {
      if (part !== '') chunks.push(part);
