/** `TextWrapper._handle_long_word` with `break_long_words` enabled. */
function handleLongWord(pending, currentLine, currentLength, width) {
  const spaceLeft = width < 1 ? 1 : width - currentLength;
  const chunk = pending[pending.length - 1];

  let end = spaceLeft;
  if (chunk.length > spaceLeft) {
    const hyphen = chunk.lastIndexOf('-', spaceLeft - 1);
    if (hyphen > 0 && [...chunk.slice(0, hyphen)].some((c) => c !== '-')) {
      end = hyphen + 1;
    }
  }

  currentLine.push(chunk.slice(0, end));
  pending[pending.length - 1] = chunk.slice(end);
}

/**
 * `textwrap.wrap(text, width)`.
 *
 * @param {string} text
 * @param {number} width
 * @returns {string[]}
 */
export function wrap(text, width) {
  if (width <= 0) {
    throw new PyValueError(`invalid width ${width} (must be > 0)`);
  }

  // Kept as a stack whose top is the last element, matching CPython's reversed
  // chunk list so that the control flow below can be compared line by line.
  const pending = splitChunks(text).reverse();
  const lines = [];

  while (pending.length > 0) {
    const currentLine = [];
    let currentLength = 0;

    if (isBlank(pending[pending.length - 1]) && lines.length > 0) pending.pop();

    while (pending.length > 0) {
      const chunkLength = pending[pending.length - 1].length;
      if (currentLength + chunkLength > width) break;
      currentLine.push(pending.pop());
      currentLength += chunkLength;
    }

    if (pending.length > 0 && pending[pending.length - 1].length > width) {
      handleLongWord(pending, currentLine, currentLength, width);
      if (pending[pending.length - 1] === '') pending.pop();
    }

    if (currentLine.length > 0 && isBlank(currentLine[currentLine.length - 1])) {
      currentLine.pop();
    }

    if (currentLine.length > 0) lines.push(currentLine.join(''));
  }

  return lines;
}
