/**
 * `shutil.get_terminal_size()`, restricted to the column count that argparse
 * needs in order to lay out its usage and help text.
 */

import { pyInt } from './int.mjs';

const FALLBACK_COLUMNS = 80;

/**
 * COLUMNS wins when it parses to a positive integer -- and it is parsed with
 * Python's `int()`, so a padded value such as " 30 " is still honoured. Only if
 * that fails does the size of the controlling terminal come into play, and a
 * redirected stdout falls back to 80 columns.
 *
 * @returns {number}
 */
export function getTerminalColumns() {
  const fromEnvironment = process.env.COLUMNS;
  if (fromEnvironment !== undefined) {
    try {
      const columns = Number(pyInt(fromEnvironment));
      if (columns > 0) return columns;
    } catch {
      // A malformed COLUMNS is ignored exactly as ValueError is in shutil.
    }
  }

  const stdout = process.stdout;
  if (stdout && stdout.isTTY && typeof stdout.columns === 'number' && stdout.columns > 0) {
    return stdout.columns;
  }

  return FALLBACK_COLUMNS;
}
