/**
 * Command-line recovery with CPython's `surrogateescape` semantics.
 *
 * Python decodes `argv` as UTF-8 with `errors='surrogateescape'`, so a byte that
 * is not valid UTF-8 survives as a lone surrogate and shows up verbatim in a
 * `repr()`. Node has already lossily decoded `process.argv` by the time user
 * code runs, replacing such bytes with U+FFFD, so the original bytes are read
 * back from the kernel when that is possible.
 *
 * This is a fidelity refinement, not a load-bearing path: whenever the raw
 * bytes cannot be lined up with `process.argv` the lossy strings are used.
 */

import { readFileSync } from 'node:fs';

/** Decode UTF-8, mapping every byte that cannot be decoded to U+DC00 + byte. */
function decodeSurrogateescape(bytes) {
  let out = '';
  let index = 0;

  while (index < bytes.length) {
    const lead = bytes[index];

    let length = 0;
    let codePoint = 0;
    let lowerBound = 0;
    if (lead < 0x80) {
      out += String.fromCharCode(lead);
      index += 1;
      continue;
    } else if (lead >= 0xc2 && lead <= 0xdf) {
      length = 2;
      codePoint = lead & 0x1f;
      lowerBound = 0x80;
    } else if (lead >= 0xe0 && lead <= 0xef) {
      length = 3;
      codePoint = lead & 0x0f;
      lowerBound = 0x800;
    } else if (lead >= 0xf0 && lead <= 0xf4) {
      length = 4;
      codePoint = lead & 0x07;
      lowerBound = 0x10000;
    } else {
      out += String.fromCharCode(0xdc00 + lead);
      index += 1;
      continue;
    }

    let valid = index + length <= bytes.length;
    if (valid) {
      for (let offset = 1; offset < length; offset += 1) {
        const continuation = bytes[index + offset];
        if ((continuation & 0xc0) !== 0x80) {
          valid = false;
          break;
        }
        codePoint = (codePoint << 6) | (continuation & 0x3f);
      }
    }
    // Overlong forms, encoded surrogates and out-of-range code points are all
    // errors, and the error handler only ever consumes the leading byte.
    if (
      !valid ||
      codePoint < lowerBound ||
      codePoint > 0x10ffff ||
      (codePoint >= 0xd800 && codePoint <= 0xdfff)
    ) {
      out += String.fromCharCode(0xdc00 + lead);
      index += 1;
      continue;
    }

    out += String.fromCodePoint(codePoint);
    index += length;
  }

  return out;
}

function readRawCommandLine() {
  const raw = readFileSync('/proc/self/cmdline');
  const fields = [];
  let start = 0;
  for (let index = 0; index < raw.length; index += 1) {
    if (raw[index] === 0) {
      fields.push(raw.subarray(start, index));
      start = index + 1;
    }
  }
  if (start < raw.length) fields.push(raw.subarray(start));
  return fields;
}

/**
 * The equivalent of `sys.argv[1:]`.
 *
 * @returns {string[]}
 */
export function getArgv() {
  const lossy = process.argv.slice(2);

  try {
    const fields = readRawCommandLine();
    if (fields.length >= lossy.length) {
      const tail = fields.slice(fields.length - lossy.length);
      // Node strips its own options from process.argv, so only trust the raw
      // bytes when their lossy decoding reproduces what Node reported.
      const aligns = tail.every((bytes, i) => bytes.toString('utf8') === lossy[i]);
      if (aligns) return tail.map(decodeSurrogateescape);
    }
  } catch {
    // No procfs, or an unreadable cmdline: the lossy strings are good enough.
  }

  return lossy;
}

/**
 * The equivalent of `os.path.basename(sys.argv[0])`, used as argparse's default
 * program name.
 *
 * @returns {string}
 */
export function getProgramName() {
  const script = process.argv[1];
  if (typeof script !== 'string' || script === '') return 'python';
  const segments = script.split('/');
  return segments[segments.length - 1] || script;
}
