/**
 * Blocking writes to the standard streams.
 *
 * argparse prints its usage and then terminates the process immediately, and
 * Node's buffered stream writes are not guaranteed to have been flushed by the
 * time `process.exit()` tears the process down when stdout is a pipe. Writing
 * through the file descriptor keeps the output ordered and complete.
 */

import { writeSync } from 'node:fs';

const STDOUT = 1;
const STDERR = 2;

function writeAll(fd, text) {
  const bytes = Buffer.from(text, 'utf8');
  let written = 0;
  while (written < bytes.length) {
    try {
      written += writeSync(fd, bytes, written, bytes.length - written);
    } catch (error) {
      // A non-blocking pipe that is momentarily full reports EAGAIN; retrying is
      // the only thing to do, and any other failure is genuinely fatal.
      if (error && (error.code === 'EAGAIN' || error.code === 'EWOULDBLOCK')) continue;
      throw error;
    }
  }
}

/** Write to stdout with no added newline (`sys.stdout.write`). */
export function writeStdout(text) {
  writeAll(STDOUT, text);
}

/** Write to stderr with no added newline (`sys.stderr.write`). */
export function writeStderr(text) {
  writeAll(STDERR, text);
}
