/**
 * Stand-ins for the CPython exception types this port needs to distinguish.
 *
 * Only the pieces the migration relies on are modelled: `argparse` catches
 * `ValueError` and `TypeError` coming out of an argument's `type` callable and
 * turns them into its own "invalid <type> value" message, so the port needs the
 * two to be tellable apart from ordinary JavaScript errors.
 */

export class PyException extends Error {
  constructor(message) {
    super(message);
    this.name = this.constructor.name;
  }
}

export class PyValueError extends PyException {}

export class PyTypeError extends PyException {}

/**
 * Raised in place of CPython's `SystemExit`. The entry point catches it so that
 * the process exits with argparse's status code instead of a stack trace.
 */
export class SystemExit extends PyException {
  constructor(code = 0) {
    super(`SystemExit: ${code}`);
    this.code = code;
  }
}
